use serde_json::json;

use super::BuiltinTool as T;

/// Every builtin tool with the tier it acts at (`reads` changes nothing,
/// `writes` changes files or durable state, `runs` executes commands or code)
/// and the arguments it reads. Approval, plan mode, the capability policy and
/// the tool specs offered to the model all read them from here, so a tool is
/// described once, where it is declared.
pub(super) fn built_in_tools() -> Vec<T> {
    vec![
        T::reads("list_dir", "List a directory under cwd; limit (required) is how many entries to answer; depth recursively includes children that many levels down").input(json!({"path": {"type": "string"}, "limit": {"type": "number"}, "depth": {"type": "number"}}), &[]),
        T::runs("read", "Unified reader routing local selectors, artifact://, mcp://, HTTP(S), archive entries, SQLite rows, notebooks, documents, and text files"),
        T::reads("read_file", "Read a UTF-8 text file under cwd, whole or the lines a selector names; returns sha256, snapshot path#TAG, visual numbered lines, content; selectors support ranges, comma ranges, raw, and conflicts").input(json!({"path": {"type": "string"}}), &["path"]),
        T::reads("read_binary_file", "Read one binary file under cwd as base64; maxBytes (required) is how many bytes to send").input(json!({"path": {"type": "string"}, "maxBytes": {"type": "number"}}), &["path"]),
        T::reads("read_image", "Visually inspect a PNG, JPEG, GIF, or WebP image under cwd. Complete image bytes are attached to the next model request; no separate OCR tool is needed. maxBytes (required) is how many bytes to read; an image cut short is refused rather than sent.").input(json!({"path": {"type": "string"}, "maxBytes": {"type": "number"}}), &["path"]),
        T::reads("read_archive", "List archive entries or read one entry from .zip, .tar, .tar.gz, or .tgz under cwd as text, binary base64, document text, or image metadata; reading an entry requires maxBytes, how many bytes to answer; text/document entries support line ranges").input(json!({"path": {"type": "string"}, "entry": {"type": "string"}, "mode": {"type": "string"}, "maxBytes": {"type": "number"}, "range": {"type": "string"}}), &["path"]),
        T::reads("read_document", "Extract readable text from one document under cwd; supports text, HTML, JSON, CSV/TSV, XML/RSS/Atom, notebooks, and basic PDF text streams; supports line ranges; maxBytes (required) is how many bytes of text to answer").input(json!({"path": {"type": "string"}, "maxBytes": {"type": "number"}, "range": {"type": "string"}}), &["path"]),
        T::reads("read_sqlite", "Read a SQLite database under cwd: list tables, inspect a table, fetch one row by primary key, or run a read-only SELECT/WITH query; reading rows (a query, or a table without key) requires limit, how many rows to answer").input(json!({"path": {"type": "string"}, "table": {"type": "string"}, "key": {"type": "string"}, "query": {"type": "string"}, "limit": {"type": "number"}, "offset": {"type": "number"}, "where": {"type": "string"}, "order": {"type": "string"}}), &["path"]),
        T::reads("search_text", "Search one file for a literal string and answer every matching line; case-insensitive by default").input(json!({"path": {"type": "string"}, "query": {"type": "string"}, "caseSensitive": {"type": "boolean"}}), &["path", "query"]),
        T::reads("search_files", "Recursively search text files under cwd for a literal string; limit (required) is how many matches to answer; supports path/paths, hidden, gitignore, caseSensitive, and skip; case-insensitive by default").input(json!({"path": {"type": "string"}, "paths": {"type": "array", "items": {"type": "string"}}, "query": {"type": "string"}, "hidden": {"type": "boolean"}, "gitignore": {"type": "boolean"}, "caseSensitive": {"type": "boolean"}, "limit": {"type": "number"}, "skip": {"type": "number"}}), &["query"]),
        T::reads("glob_paths", "Find files and directories under cwd with simple glob patterns; supports * and ** plus hidden, gitignore, limit (required: how many paths to answer), and skip").input(json!({"patterns": {"type": "string"}, "path": {"type": "string"}, "hidden": {"type": "boolean"}, "gitignore": {"type": "boolean"}, "limit": {"type": "number"}, "skip": {"type": "number"}}), &[]),
        T::reads("grep_regex", "Search text files under cwd with a regular expression; limit (required) is how many matches to answer; supports path/paths, hidden, gitignore, multiline, caseSensitive, and skip; case-insensitive by default").input(json!({"expr": {"type": "string"}, "path": {"type": "string"}, "paths": {"type": "array", "items": {"type": "string"}}, "hidden": {"type": "boolean"}, "gitignore": {"type": "boolean"}, "multiline": {"type": "boolean"}, "caseSensitive": {"type": "boolean"}, "limit": {"type": "number"}, "skip": {"type": "number"}}), &["expr"]),
        T::writes("write_file", "Create or overwrite a UTF-8 text file under cwd; overwrites require expectedSha256 from read_file; returns sha256 and visual diff; requires write-tier approval (--allow-write)").input(json!({"path": {"type": "string"}, "content": {"type": "string"}, "expectedSha256": {"type": "string"}}), &["path", "content"]),
        T::writes("write", "Unified revision-guarded writer routing normal and notebook files, archive entries, and SQLite row mutations; requires write-tier approval (--allow-write)"),
        T::writes("write_archive", "Atomically upsert or delete a safe entry in zip/tar archives with expectedSha256 revision guard; requires write-tier approval (--allow-write)"),
        T::writes("write_sqlite", "Run parameterized insert, update, or delete in an immediate SQLite transaction with expectedSha256 revision guard; requires write-tier approval (--allow-write)"),
        T::writes("apply_patch", "Apply exact one-occurrence string replacements to an existing UTF-8 file; returns sha256 and visual diff; requires expectedSha256 and write-tier approval (--allow-write)").input(json!({"path": {"type": "string"}, "expectedSha256": {"type": "string"}, "replacements": {"type": "array"}}), &["path", "expectedSha256", "replacements"]),
        T::writes("edit_file", "Apply line-based edits to a UTF-8 file under cwd; returns sha256 and visual diff; requires expectedSha256 and write-tier approval (--allow-write)").input(json!({"path": {"type": "string"}, "expectedSha256": {"type": "string"}, "ops": {"type": "array", "items": {"type": "object", "properties": {"op": {"type": "string", "enum": crate::tool_runtime::LineEditKind::names()}, "start": {"type": "number"}, "end": {"type": "number"}, "content": {"type": ["string", "array"]}}, "required": ["op", "start"]}}}), &["path", "expectedSha256", "ops"]),
        T::writes("edit", "Apply a Jeden anchored visual patch string with [path#TAG], SWAP/DEL/INS/REM/MV and safe block hunks; returns visual diffs; requires write-tier approval (--allow-write)").input(json!({"patch": {"type": "string"}}), &["patch"]),
        T::writes("delete_file", "Delete one UTF-8 file under cwd; returns visual diff; requires expectedSha256 and write-tier approval (--allow-write)").input(json!({"path": {"type": "string"}, "expectedSha256": {"type": "string"}}), &["path", "expectedSha256"]),
        T::writes("move_file", "Move or rename one file under cwd; returns rename preview; requires expectedSha256 and write-tier approval (--allow-write)").input(json!({"from": {"type": "string"}, "to": {"type": "string"}, "expectedSha256": {"type": "string"}, "overwrite": {"type": "boolean"}}), &["from", "to", "expectedSha256"]),
        T::runs("run_command", "Run a shell command in cwd; runs until the command ends or the operation is cancelled; requires exec-tier approval (--allow-command)").input(json!({"command": {"type": "string"}}), &["command"]),
        T::runs("run_process", "Run one process with argv array in cwd without a shell; supports env overrides; runs until the process ends or the operation is cancelled; requires exec-tier approval (--allow-command)").input(json!({"command": {"type": "string"}, "args": {"type": "array", "items": {"type": "string"}}, "stdin": {"type": "string"}, "env": {"type": "object"}}), &["command"]),
        T::runs("node_eval", "Run JavaScript with node --input-type=module in cwd; runs until it ends or the operation is cancelled; requires exec-tier approval (--allow-command)").input(json!({"code": {"type": "string"}}), &["code"]),
        T::runs("python_eval", "Run Python code with python3 in cwd; runs until it ends or the operation is cancelled; requires exec-tier approval (--allow-command)").input(json!({"code": {"type": "string"}}), &["code"]),
        T::runs("eval_session", "Evaluate code in a bounded persistent Python or JavaScript kernel; state survives calls and reset starts a clean kernel; requires --allow-command").probe_backed(),
        T::runs("pty_session", "Send input to a persistent bounded pseudo-terminal shell with streamed output, reset, and cancellation; requires --allow-command").probe_backed(),
        T::runs("pty_resize", "Resize a live persistent pseudo-terminal session without spawning a new process; requires --allow-command").probe_backed(),
        T::runs("ast_search", "Run a tree-sitter structural query against Rust, Python, JavaScript, or TypeScript and return captured syntax nodes; limit (required) is how many to answer").probe_backed(),
        T::writes("ast_rewrite", "Preview a tree-sitter captured-node rewrite as a pending action, then atomically apply or discard it; the preview holds until applied or discarded and lands only on the file revision it was made against").probe_backed(),
        T::runs("lsp", "Use an automatically discovered persistent language server for health, diagnostics, definition, references, rename, code actions, or formatting").probe_backed(),
        T::reads("list_package_scripts", "List package.json scripts in cwd").input(json!({}), &[]),
        T::runs("run_package_script", "Run one existing package.json script with npm; supports env overrides; runs until the script ends or the operation is cancelled; requires exec-tier approval (--allow-command or interactive approval)").input(json!({"script": {"type": "string"}, "env": {"type": "object"}}), &["script"]),
        T::reads("git_status", "Read git status --short for cwd").input(json!({}), &[]),
        T::reads("git_diff", "Read git diff for cwd or one path under cwd").input(json!({"path": {"type": "string"}}), &[]),
        T::reads("git_log", "Read recent git commits for cwd or one path under cwd; limit (required) is how many commits to answer").input(json!({"limit": {"type": "number"}, "path": {"type": "string"}}), &[]),
        T::reads("git_show", "Read one git object or commit summary; optional path scopes the output").input(json!({"ref": {"type": "string"}, "path": {"type": "string"}}), &[]),
        T::reads("fetch_url", "Fetch one HTTP(S) URL and return its text up to maxBytes (required: how many bytes to keep, half from the start and half from the end) with byte count, truncation state, SHA-256, and optional line range; runs until the server answers").input(json!({"url": {"type": "string"}, "maxBytes": {"type": "number"}, "range": {"type": "string"}}), &["url"]),
        T::reads("fetch_readable_url", "Fetch one HTTP(S) URL and return simplified readable text up to maxBytes (required) with byte count, truncation state, SHA-256, and optional line range; supports HTML, JSON, CSV/TSV, RSS/Atom/XML, notebooks, and basic PDF text streams; runs until the server answers").input(json!({"url": {"type": "string"}, "maxBytes": {"type": "number"}, "range": {"type": "string"}}), &["url"]),
        T::writes("save_artifact", "Save UTF-8 content under a name in the current session artifacts directory").input(json!({"name": {"type": "string"}, "content": {"type": "string"}}), &["name", "content"]),
        T::reads("list_artifacts", "List files in the current session artifact directory").input(json!({}), &[]),
        T::reads("read_artifact", "Read one UTF-8 artifact from the current session artifact directory; maxBytes (required) is how many bytes to answer").input(json!({"name": {"type": "string"}, "maxBytes": {"type": "number"}}), &["name"]),
        T::runs("recall_conversation", "Recall a session's conversation; defaults to the current session, or pass session=<id-or-path>. With id and n from a chat memory line `id+n|`, open that line into the two lines it was made from, or for a line of a single message give the message whole (zoom). With date=<id>, give the date and time of message id. Without either, the text-only transcript (user prompts and final answers).").input(json!({"session": {"type": "string"}, "id": {"type": ["number", "string"]}, "n": {"type": ["number", "string"]}, "date": {"type": ["number", "string"]}}), &[]),
        T::reads("ask_user", "Ask the human user a question during an interactive session. The question and answer are recorded in the operator ask register; a question the user already answered in this workspace in the same words returns that answer (fromRegister) without asking again").input(json!({"question": {"type": "string"}, "options": {"type": "array"}}), &["question"]),
        T::writes("todo", "Track retained session tasks. init/append are additive and take phase, the name of the phase the items join (in list, each entry names its own phase); start begins work; done requests independent verification and never marks work complete. drop/rm may withdraw only agent-created planning items, never user tasks. Use stable task ids from view.").input(json!({"op": {"type": "string", "enum": crate::completion::TodoOp::names()}, "list": {"type": "array"}, "phase": {"type": "string"}, "items": {"type": "array"}, "task": {"type": "string"}}), &["op"]),
        T::reads("task_evidence", "Read one checksum-validated tool receipt from a Jeden session in this workspace. Session and event ids come from Jeden's evidence index or a tool result's jedenEvidence field.").input(json!({"sessionPath": {"type": "string"}, "eventId": {"type": "string"}}), &["sessionPath", "eventId"]),
        T::runs("delegate_task", "Run a focused subtask through the bounded durable TaskScheduler in a fresh Jeden session and return its typed child-session result; requires exec-tier approval").input(json!({"task": {"type": "string"}, "maxSteps": {"type": "number"}}), &["task"]),
        T::writes("memory", "Remember and recall durable scoped notes across Jeden sessions; list and recall require limit, how many notes to answer; context requires query and maxChars, how many characters of context to answer").input(json!({"op": {"type": "string"}, "text": {"type": "string"}, "query": {"type": "string"}, "tags": {"type": "array"}, "limit": {"type": "number"}, "maxChars": {"type": "number"}, "kind": {"type": "string"}, "scope": {"type": "object"}, "confidence": {"type": "number"}}), &["op"]),
        T::reads("context_recommend", "Ask the context advisor what to read for a task instead of searching: ranked locators from every readable file, Jeden memory, the Transcript Lake archive and the Wisent ground-truth index, plus the state of every source that answered nothing. Sources: files, ground-truth, memory, transcripts, all. Every source runs to completion.").input(json!({"query": {"type": "string"}, "limit": {"type": "number"}, "sources": {"type": "string"}}), &["query"]),
        T::writes("mcp_list_tools", "List tools from a configured stdio MCP server").input(json!({"server": {"type": "string"}}), &["server"]),
        T::writes("mcp_call_tool", "Call one tool on a configured stdio MCP server; the call runs until the server answers").input(json!({"server": {"type": "string"}, "tool": {"type": "string"}, "args": {"type": "object"}}), &["server", "tool"]),
        T::writes("mcp_list_resources", "List resources from a configured stdio MCP server").input(json!({"server": {"type": "string"}}), &["server"]),
        T::writes("mcp_read_resource", "Read one resource from a configured stdio MCP server").input(json!({"server": {"type": "string"}, "uri": {"type": "string"}}), &["server", "uri"]),
        T::writes("mcp_list_prompts", "List prompts from a configured stdio MCP server").input(json!({"server": {"type": "string"}}), &["server"]),
        T::writes("mcp_get_prompt", "Get one prompt from a configured stdio MCP server").input(json!({"server": {"type": "string"}, "name": {"type": "string"}, "args": {"type": "object"}}), &["server", "name"]),
    ]
}
